_satellite.__registerScript('https://assets.adobedtm.com/79b3942b8dfa/604ce2434de1/58216e635e6a/RCf49df29716b4421397d1fc35c61e9369-source.min.js', "<style>\n  .hero .hero .hero__image { opacity: 1 }\n</style>\n<script>\n  /* Code added in for Ask Ansys widget. Has nothing to do with Formulayt-Marketo project. This code will be moved into its own library in a couple of days */\n$(function () {\n    const thepath = window.location.pathname.toLowerCase();\n\n    const isLocalePage = /^\\/[a-z]{2}-[a-z]{2}(\\/|$)/.test(thepath);\n    const isSearchPage = thepath.includes('/search');\n\n    if (!isLocalePage && !isSearchPage) {\n        $('#floating-icon').addClass('bc-visible');\n    }\n});\n</script>");